158→export interface SendMessageInput {
159→  channel_id: string;
160→  content: string;
161→  tts?: boolean;
162→}
163→
164→export const sendMessage = tool({
165→  description: 'Send a message to a Discord channel with optional text-to-speech.',
166→  inputSchema: jsonSchema<SendMessageInput>({
167→    type: 'object',
168→    properties: {
169→      channel_id: { type: 'string', description: 'The ID of the channel to send the message to.' },
170→      content: { type: 'string', description: 'The message content (up to 2000 characters).' },
171→      tts: {
172→        type: 'boolean',
173→        description: 'Whether this message should be sent as text-to-speech.',
174→      },
175→    },
176→    required: ['channel_id', 'content'],
177→    additionalProperties: false,
178→  }),
179→  async execute(input: SendMessageInput): Promise<DiscordMessage> {
180→    try {
181→      if (!input.channel_id || !input.content) {
182→        throw new Error('channel_id and content are required and must be non-empty');
183→      }
184→      if (input.content.length > 2000) {
185→        throw new Error('Message content must be 2000 characters or less');
186→      }
187→      return await apiRequest<DiscordMessage>('POST', `/channels/${input.channel_id}/messages`, {
188→        content: input.content,
189→        tts: input.tts,
190→      });
191→    } catch (error) {
192→      throw new Error(`Failed to send message: ${(error as Error).message}`);
193→    }
194→  },
195→});
