205→export const listMessages = tool({
206→  description:
207→    'Get recent messages from a Discord channel with optional pagination using message IDs.',
208→  inputSchema: jsonSchema<ListMessagesInput>({
209→    type: 'object',
210→    properties: {
211→      channel_id: { type: 'string', description: 'The ID of the channel to get messages from.' },
212→      limit: {
213→        type: 'number',
214→        description: 'Number of messages to retrieve (1-100, default: 50).',
215→      },
216→      before: { type: 'string', description: 'Get messages before this message ID.' },
217→      after: { type: 'string', description: 'Get messages after this message ID.' },
218→      around: { type: 'string', description: 'Get messages around this message ID.' },
219→    },
220→    required: ['channel_id'],
221→    additionalProperties: false,
222→  }),
223→  async execute(input: ListMessagesInput): Promise<DiscordMessage[]> {
224→    try {
225→      if (!input.channel_id) {
226→        throw new Error('channel_id is required');
227→      }
228→      if (input.limit !== undefined && (input.limit < 1 || input.limit > 100)) {
229→        throw new Error('Limit must be between 1 and 100');
230→      }
231→      const qs = buildQueryString({
232→        limit: input.limit,
233→        before: input.before,
234→        after: input.after,
235→        around: input.around,
236→      });
237→      return await apiRequest<DiscordMessage[]>(
238→        'GET',
239→        `/channels/${input.channel_id}/messages${qs}`
240→      );
241→    } catch (error) {
242→      throw new Error(`Failed to list messages: ${(error as Error).message}`);
243→    }
244→  },
245→});
