510→export interface CreateChannelInput {
511→  guild_id: string;
512→  name: string;
513→  type?: number;
514→  topic?: string;
515→  parent_id?: string;
516→}
517→
518→const VALID_CHANNEL_TYPES = [0, 2, 4, 5];
519→
520→export const createChannel = tool({
521→  description:
522→    'Create a new channel in a Discord guild. Channel types: 0=text, 2=voice, 4=category, 5=announcement.',
523→  inputSchema: jsonSchema<CreateChannelInput>({
524→    type: 'object',
525→    properties: {
526→      guild_id: { type: 'string', description: 'The ID of the guild to create the channel in.' },
527→      name: { type: 'string', description: 'The name of the channel (1-100 characters).' },
528→      type: {
529→        type: 'number',
530→        description: 'Channel type: 0=text, 2=voice, 4=category, 5=announcement (default: 0).',
531→      },
532→      topic: {
533→        type: 'string',
534→        description: 'Channel topic (0-1024 characters, text channels only).',
535→      },
536→      parent_id: {
537→        type: 'string',
538→        description: 'ID of the parent category for the channel.',
539→      },
540→    },
541→    required: ['guild_id', 'name'],
542→    additionalProperties: false,
543→  }),
544→  async execute(input: CreateChannelInput): Promise<DiscordChannel> {
545→    try {
546→      if (!input.guild_id || !input.name) {
547→        throw new Error('guild_id and name are required');
548→      }
549→      if (input.name.length < 1 || input.name.length > 100) {
550→        throw new Error('Channel name must be between 1 and 100 characters');
551→      }
552→      if (input.type !== undefined && !VALID_CHANNEL_TYPES.includes(input.type)) {
553→        throw new Error(
554→          'Channel type must be 0 (text), 2 (voice), 4 (category), or 5 (announcement)'
555→        );
556→      }
557→      if (input.topic !== undefined && input.topic.length > 1024) {
558→        throw new Error('Topic must be 1024 characters or less');
559→      }
560→      return await apiRequest<DiscordChannel>('POST', `/guilds/${input.guild_id}/channels`, {
561→        name: input.name,
562→        type: input.type ?? 0,
563→        topic: input.topic,
564→        parent_id: input.parent_id,
565→      });
566→    } catch (error) {
567→      throw new Error(`Failed to create channel: ${(error as Error).message}`);
568→    }
569→  },
570→});
