// Third-party integration tools
export { googleSearch } from './google-search.js';
export type { GoogleSearchResult, GoogleSearchResponse, GoogleSearchInput } from './google-search.js';

export { httpRequest } from './http-request.js';
export type { HttpRequestResult, HttpRequestInput } from './http-request.js';

export { textToSpeech } from './openai-tts.js';
export type { TextToSpeechResult, TextToSpeechInput } from './openai-tts.js';

export { createStripeInvoice } from './stripe-invoice.js';
export type { StripeInvoiceResult, StripeLineItem, CreateStripeInvoiceInput } from './stripe-invoice.js';

export { searchPhotos, getRandomPhoto, getPhoto } from './unsplash.js';
export type {
  UnsplashPhoto,
  UnsplashPhotoUrls,
  UnsplashPhotoUser,
  UnsplashPhotoLinks,
  SearchPhotosResult,
  GetPhotoResult,
  SearchPhotosInput,
  GetRandomPhotoInput,
  GetPhotoInput,
} from './unsplash.js';

export { firecrawlScrape } from './firecrawl.js';
export type { FirecrawlScrapeResult, FirecrawlScrapeInput } from './firecrawl.js';

export { triggerZapierWebhook } from './zapier-webhook.js';
export type { TriggerWebhookResult, TriggerZapierWebhookInput } from './zapier-webhook.js';

export { createIssue, createPullRequest, getRepoInfo, listPullRequests, getFileContent, listCommits } from './github.js';
export type {
  CreateIssueResult,
  CreatePullRequestResult,
  RepoInfoResult,
  PullRequestSummary,
  FileContentResult,
  CommitSummary,
  CreateIssueInput,
  CreatePullRequestInput,
  GetRepoInfoInput,
  ListPullRequestsInput,
  GetFileContentInput,
  ListCommitsInput,
} from './github.js';

export { readSheet, writeSheet, appendSheet, clearSheet } from './google-sheets.js';
export type {
  ReadSheetResult,
  WriteSheetResult,
  AppendSheetResult,
  ClearSheetResult,
  ReadSheetInput,
  WriteSheetInput,
  AppendSheetInput,
  ClearSheetInput,
} from './google-sheets.js';

export { notionSearch, notionQueryDatabase, notionGetPage, notionCreatePage } from './notion.js';
export type {
  NotionSearchResultItem,
  NotionSearchResult,
  NotionQueryResultItem,
  NotionQueryResult,
  NotionPageResult,
  NotionCreatePageResult,
  NotionSearchInput,
  NotionQueryDatabaseInput,
  NotionGetPageInput,
  NotionCreatePageInput,
} from './notion.js';

export { postTweet, searchTweets, getUserProfile, getUserTweets } from './twitter.js';
export type {
  PostTweetResult,
  SearchTweetItem,
  SearchTweetsResult,
  UserProfileResult,
  UserTweetItem,
  UserTweetsResult,
  PostTweetInput,
  SearchTweetsInput,
  GetUserProfileInput,
  GetUserTweetsInput,
} from './twitter.js';

export { searchVideos, getVideoDetails, listChannelVideos, getTranscript } from './youtube.js';
export type {
  SearchVideoItem,
  SearchVideosResult,
  VideoDetailsResult,
  ChannelVideoItem,
  ChannelVideosResult,
  TranscriptSegment,
  TranscriptResult,
  SearchVideosInput,
  GetVideoDetailsInput,
  ListChannelVideosInput,
  GetTranscriptInput,
} from './youtube.js';

export { searchEmails, readEmail, sendGmail } from './gmail.js';
export type {
  SearchEmailsResult,
  ReadEmailResult,
  SendGmailResult,
  SearchEmailsInput,
  ReadEmailInput,
  SendGmailInput,
} from './gmail.js';

export { listFolder, uploadFile, downloadFile, deleteFile, createFolder, createSharedLink } from './dropbox.js';
export type {
  ListFolderOutput,
  UploadFileOutput,
  DownloadFileOutput,
  DeleteFileOutput,
  CreateFolderOutput,
  CreateSharedLinkOutput,
  ListFolderInput,
  UploadFileInput,
  DownloadFileInput,
  DeleteFileInput,
  CreateFolderInput,
  CreateSharedLinkInput,
} from './dropbox.js';

export { listDriveFiles, uploadDriveFile, downloadDriveFile, createDriveFolder, shareDriveFile } from './google-drive.js';
export type {
  ListDriveFilesOutput,
  UploadDriveFileOutput,
  DownloadDriveFileOutput,
  CreateDriveFolderOutput,
  ShareDriveFileOutput,
  ListDriveFilesInput,
  UploadDriveFileInput,
  DownloadDriveFileInput,
  CreateDriveFolderInput,
  ShareDriveFileInput,
} from './google-drive.js';

export { createPresentation, getPresentation, addSlide } from './google-slides.js';
export type {
  CreatePresentationOutput,
  GetPresentationOutput,
  AddSlideOutput,
  CreatePresentationInput,
  GetPresentationInput,
  AddSlideInput,
} from './google-slides.js';

// Agnt platform API tools
export {
  listAgents,
  getAgent,
  createAgent,
  updateAgent,
  deleteAgent,
  chatWithAgent,
  listWorkflows,
  getWorkflow,
  createWorkflow,
  deleteWorkflow,
  startWorkflow,
  stopWorkflow,
  getWorkflowStatus,
  generateWorkflow,
  generateAgent,
  listGoals,
  createGoal,
  executeGoal,
  getGoalStatus,
  deleteGoal,
  orchestratorChat,
  listExecutions,
  getExecution,
  listCustomTools,
  createCustomTool,
  deleteCustomTool,
} from './platform.js';
export type {
  AgntAgent,
  AgntWorkflow,
  AgntGoal,
  AgntExecution,
  AgntCustomTool,
  AgntChatResponse,
