  1→import { prisma } from '@tpmjs/db';
  2→import { fetchLatestPackageWithMetadata } from '@tpmjs/npm-client';
  3→import type { TpmjsToolDefinition } from '@tpmjs/types/tpmjs';
  4→import { validateTpmjsField } from '@tpmjs/types/tpmjs';
  5→import { type NextRequest, NextResponse } from 'next/server';
  6→import { env } from '~/env';
  7→import { performHealthCheck } from '~/lib/health-check/health-check-service';
  8→import {
  9→  convertJsonSchemaToParameters,
 10→  extractToolSchema,
 11→  listToolExports,
 12→} from '~/lib/schema-extraction';
 13→
 14→export const runtime = 'nodejs';
 15→export const dynamic = 'force-dynamic';
 16→export const maxDuration = 60;
 17→
 18→/**
 19→ * POST /api/sync/package
 20→ * Manually sync a specific package by name
 21→ *
 22→ * Body: { packageName: string }
 23→ * Requires Authorization: Bearer <CRON_SECRET>
 24→ */
 25→export async function POST(request: NextRequest) {
 26→  // Verify cron secret for security
 27→  const authHeader = request.headers.get('authorization');
 28→  const token = authHeader?.replace('Bearer ', '');
 29→
 30→  if (env.CRON_SECRET && token !== env.CRON_SECRET) {
 31→    return NextResponse.json({ success: false, error: 'Unauthorized' }, { status: 401 });
 32→  }
 33→
 34→  try {
 35→    const body = await request.json();
 36→    const packageName = body.packageName;
 37→
 38→    if (!packageName || typeof packageName !== 'string') {
 39→      return NextResponse.json(
 40→        { success: false, error: 'packageName is required' },
 41→        { status: 400 }
 42→      );
 43→    }
 44→
 45→    // Fetch full package metadata
 46→    const pkg = await fetchLatestPackageWithMetadata(packageName);
 47→
 48→    if (!pkg) {
 49→      return NextResponse.json(
 50→        { success: false, error: `Package ${packageName} not found on npm` },
 51→        { status: 404 }
 52→      );
 53→    }
 54→
 55→    // Check if package has tpmjs keyword
 56→    const hasTpmjsKeyword = pkg.keywords?.includes('tpmjs') || pkg.keywords?.includes('tpmjs-tool');
 57→
 58→    if (!hasTpmjsKeyword) {
 59→      return NextResponse.json(
 60→        { success: false, error: `Package ${packageName} does not have tpmjs keyword` },
 61→        { status: 400 }
 62→      );
 63→    }
 64→
 65→    // Determine validation based on tpmjs field presence
 66→    let validation: ReturnType<typeof validateTpmjsField>;
 67→
 68→    if (!pkg.tpmjs) {
 69→      // No tpmjs field - use auto-discovery with default category
 70→      console.log(
 71→        `Package ${pkg.name} has tpmjs keyword but no tpmjs field - using auto-discovery`
 72→      );
 73→      validation = {
 74→        valid: true,
 75→        tier: 'minimal',
 76→        packageData: {
 77→          category: 'utilities',
 78→        },
 79→        tools: [],
 80→        needsAutoDiscovery: true,
 81→        wasLegacyFormat: false,
 82→      };
 83→    } else {
 84→      validation = validateTpmjsField(pkg.tpmjs);
 85→      if (!validation.valid || !validation.packageData) {
 86→        return NextResponse.json(
 87→          { success: false, error: 'Invalid tpmjs field in package.json' },
 88→          { status: 400 }
 89→        );
 90→      }
 91→    }
 92→
 93→    const packageData = validation.packageData!;
 94→
 95→    // Extract author name
 96→    const authorName =
 97→      typeof pkg.author === 'string'
 98→        ? pkg.author
 99→        : typeof pkg.author === 'object' && pkg.author?.name
100→          ? pkg.author.name
101→          : 'unknown';
102→
103→    // Upsert Package record
104→    const packageRecord = await prisma.package.upsert({
105→      where: { npmPackageName: pkg.name },
106→      create: {
107→        npmPackageName: pkg.name,
108→        npmVersion: pkg.version,
109→        npmPublishedAt: pkg.publishedAt ? new Date(pkg.publishedAt) : new Date(),
110→        npmDescription: pkg.description ?? undefined,
111→        npmRepository: pkg.repository ?? undefined,
112→        npmHomepage: pkg.homepage ?? undefined,
113→        npmLicense: pkg.license ?? undefined,
114→        npmKeywords: pkg.keywords || [],
115→        npmReadme: pkg.readme ?? undefined,
116→        npmAuthor: pkg.author ?? undefined,
117→        npmMaintainers: pkg.maintainers ?? undefined,
118→        category: packageData.category,
119→        env: packageData.env ?? undefined,
120→        frameworks: packageData.frameworks || [],
121→        tier: validation.tier || 'minimal',
122→        discoveryMethod: 'manual',
123→        isOfficial: false,
124→        npmDownloadsLastMonth: 0,
125→        githubStars: null,
126→      },
127→      update: {
128→        npmVersion: pkg.version,
129→        npmPublishedAt: pkg.publishedAt ? new Date(pkg.publishedAt) : new Date(),
130→        npmDescription: pkg.description ?? undefined,
131→        npmRepository: pkg.repository ?? undefined,
132→        npmHomepage: pkg.homepage ?? undefined,
133→        npmLicense: pkg.license ?? undefined,
134→        npmKeywords: pkg.keywords || [],
135→        npmReadme: pkg.readme ?? undefined,
136→        npmAuthor: pkg.author ?? undefined,
137→        npmMaintainers: pkg.maintainers ?? undefined,
138→        category: packageData.category,
139→        env: packageData.env ?? undefined,
140→        frameworks: packageData.frameworks || [],
141→        tier: validation.tier || 'minimal',
142→      },
143→    });
144→
145→    // Determine tools to process
146→    let toolsToProcess: TpmjsToolDefinition[] = validation.tools || [];
147→    let toolDiscoverySource: 'auto' | 'manual' = 'manual';
148→
149→    // If tools need auto-discovery, call the executor
150→    if (validation.needsAutoDiscovery || toolsToProcess.length === 0) {
151→      console.log(`Auto-discovering tools for ${pkg.name}...`);
152→      const exportsResult = await listToolExports(pkg.name, pkg.version, null);
153→
154→      if (exportsResult.success) {
155→        toolsToProcess = exportsResult.tools
156→          .filter((t) => t.isValidTool)
157→          .map((t) => ({
158→            name: t.name,
159→            description: t.description,
160→            parameters: undefined,
161→            returns: undefined,
162→            aiAgent: undefined,
163→          }));
164→        toolDiscoverySource = 'auto';
165→        console.log(
166→          `Auto-discovered ${toolsToProcess.length} tools for ${pkg.name}: ${toolsToProcess.map((t) => t.name).join(', ')}`
167→        );
168→      } else {
169→        return NextResponse.json(
170→          {
171→            success: false,
172→            error: `Failed to auto-discover tools: ${exportsResult.error}`,
173→            packageCreated: true,
174→            packageId: packageRecord.id,
175→          },
176→          { status: 500 }
177→        );
178→      }
179→    }
180→
181→    const syncedTools: string[] = [];
182→
183→    // Upsert each tool
184→    for (const toolDef of toolsToProcess) {
185→      const toolName = toolDef.name;
186→      if (!toolName) continue;
187→
188→      const upsertedTool = await prisma.tool.upsert({
189→        where: {
190→          packageId_name: {
191→            packageId: packageRecord.id,
192→            name: toolName,
193→          },
194→        },
195→        create: {
196→          packageId: packageRecord.id,
197→          name: toolName,
198→          description: toolDef.description || 'No description provided',
199→          // biome-ignore lint/suspicious/noExplicitAny: Prisma Json type compatibility
200→          parameters: toolDef.parameters ? (toolDef.parameters as any) : undefined,
201→          // biome-ignore lint/suspicious/noExplicitAny: Prisma Json type compatibility
202→          returns: toolDef.returns ? (toolDef.returns as any) : undefined,
203→          // biome-ignore lint/suspicious/noExplicitAny: Prisma Json type compatibility
204→          aiAgent: toolDef.aiAgent ? (toolDef.aiAgent as any) : undefined,
205→          qualityScore: null,
206→          schemaSource: toolDef.parameters ? 'author' : null,
207→          toolDiscoverySource,
208→        },
209→        update: {
210→          description: toolDef.description || undefined,
211→          // biome-ignore lint/suspicious/noExplicitAny: Prisma Json type compatibility
212→          parameters: toolDef.parameters ? (toolDef.parameters as any) : undefined,
213→          // biome-ignore lint/suspicious/noExplicitAny: Prisma Json type compatibility
214→          returns: toolDef.returns ? (toolDef.returns as any) : undefined,
215→          // biome-ignore lint/suspicious/noExplicitAny: Prisma Json type compatibility
216→          aiAgent: toolDef.aiAgent ? (toolDef.aiAgent as any) : undefined,
217→          toolDiscoverySource,
218→        },
219→      });
220→
221→      // Extract schema
222→      const schemaResult = await extractToolSchema(pkg.name, toolName, pkg.version, null);
223→
224→      if (schemaResult.success) {
225→        await prisma.tool.update({
226→          where: { id: upsertedTool.id },
227→          data: {
228→            // biome-ignore lint/suspicious/noExplicitAny: Prisma Json type compatibility
229→            inputSchema: schemaResult.inputSchema as any,
230→            // biome-ignore lint/suspicious/noExplicitAny: Prisma Json type compatibility
231→            parameters: convertJsonSchemaToParameters(schemaResult.inputSchema) as any,
232→            schemaSource: 'extracted',
233→            schemaExtractedAt: new Date(),
234→            ...(!toolDef.description && schemaResult.description
235→              ? { description: schemaResult.description }
236→              : {}),
237→          },
238→        });
239→      }
240→
241→      // Trigger health check
242→      performHealthCheck(upsertedTool.id, 'sync').catch((err) => {
243→        console.error(`Health check failed for ${pkg.name}/${toolName}:`, err);
244→      });
245→
246→      syncedTools.push(toolName);
247→    }
248→
249→    return NextResponse.json({
250→      success: true,
251→      data: {
252→        packageId: packageRecord.id,
253→        packageName: pkg.name,
254→        version: pkg.version,
255→        category: packageData.category,
256→        toolCount: syncedTools.length,
257→        tools: syncedTools,
258→        author: authorName,
259→      },
260→    });
261→  } catch (error) {
262→    console.error('Manual package sync failed:', error);
263→    return NextResponse.json(
264→      {
265→        success: false,
266→        error: error instanceof Error ? error.message : 'Unknown error',
267→      },
268→      { status: 500 }
269→    );
270→  }
271→}
