 98→          meta: { version: API_VERSION, timestamp: new Date().toISOString(), requestId },
 99→        },
100→        { status: 401 }
101→      );
102→    }
103→
104→    // Parse pagination and search params
105→    const searchParams = request.nextUrl.searchParams;
106→    const limit = Math.min(Math.max(Number.parseInt(searchParams.get('limit') || '20', 10), 1), 50);
107→    const offset = Math.max(Number.parseInt(searchParams.get('offset') || '0', 10), 0);
108→    const search = searchParams.get('search')?.trim();
109→
110→    // Fetch collections with tool count
