export interface AgntAgent {
  id: string;
  name: string;
  description?: string;
  model?: string;
  provider?: string;
  systemPrompt?: string;
  tools?: unknown[];
  createdAt?: string;
  updatedAt?: string;
}

export interface AgntWorkflow {
  id: string;
  name: string;
  description?: string;
  nodes?: unknown[];
  edges?: unknown[];
  createdAt?: string;
  updatedAt?: string;
}

export interface AgntGoal {
  id: string;
  name: string;
  description?: string;
  agentId?: string;
  steps?: unknown[];
  status?: string;
  createdAt?: string;
  updatedAt?: string;
}

export interface AgntExecution {
  id: string;
  status?: string;
  workflowId?: string;
  agentId?: string;
  result?: unknown;
  error?: string;
  startedAt?: string;
  completedAt?: string;
  createdAt?: string;
}

export interface AgntCustomTool {
  id: string;
  name: string;
  description?: string;
  schema?: unknown;
  code?: string;
  createdAt?: string;
  updatedAt?: string;
}

export interface AgntChatResponse {
  message?: string;
  conversationId?: string;
  response?: unknown;
}

export interface AgntWorkflowStatus {
  id: string;
  status: string;
  progress?: number;
  currentNode?: string;
  error?: string;
}

export interface AgntGoalStatus {
  id: string;
