333→ * Returns a map of tool name -> AI SDK tool definition
334→ *
335→ * Executor config cascade: Agent → Collection → System Default
336→ * - If agent has an executor config, it's used for all tools
337→ * - If agent has no config but collection has one, collection's config is used for tools from that collection
338→ * - If neither has config, system default is used
339→ *
340→ * Environment variables cascade: Agent → Collection (merged, agent overrides)
341→ * - Collection env vars are used as base
342→ * - Agent env vars override collection env vars for same keys
343→ * - Both are merged together for unique keys
344→ *
345→ * @param agent - The agent with tool relations
346→ * @param callerEnvVars - Optional env vars provided by the caller (for non-owners accessing public agents).
347→ *                        When provided, these are used INSTEAD of the agent's stored env vars.
348→ * @param sessionId - Optional session ID for sandbox executors
349→ * @param sandboxUrl - Optional sandbox URL for injecting sandbox tools
350→ * @param sandboxApiKey - Optional sandbox API key
351→ */
352→export function buildAgentTools(
353→  agent: AgentWithRelations,
354→  callerEnvVars?: Record<string, string>,
355→  sessionId?: string,
356→  sandboxUrl?: string,
357→  sandboxApiKey?: string
358→): Record<string, ReturnType<typeof createToolDefinition>> {
359→  const tools: Record<string, ReturnType<typeof createToolDefinition>> = {};
360→  const seenTools = new Set<string>();
361→
362→  // When callerEnvVars is provided (non-owner using public agent), use those exclusively.
363→  // Otherwise, use the agent's stored env vars.
364→  const useCallerEnvVars = callerEnvVars !== undefined;
365→  const agentEnvVars = useCallerEnvVars ? callerEnvVars : parseEnvVars(agent.envVars);
366→
367→  // Inject sandbox tools first if sandbox is enabled and session is active
368→  if (sandboxUrl && sessionId) {
369→    const sandboxTools = injectSandboxTools(sandboxUrl, sandboxApiKey, sessionId, agentEnvVars);
370→    for (const [name, toolDef] of Object.entries(sandboxTools)) {
371→      tools[name] = toolDef;
372→      // Mark sandbox tool package keys as seen to prevent duplicates
373→      // if the sandbox-shell collection is also attached
374→      seenTools.add(`@tpmjs/sandbox-shell::${name}`);
375→    }
376→  }
377→
378→  // Parse agent-level executor config
379→  const agentExecutorConfig = parseExecutorConfig(agent.executorType, agent.executorConfig);
380→
381→  // Add tools from collections first
382→  for (const agentCollection of agent.collections) {
383→    const collection = agentCollection.collection;
384→
385→    // Parse collection-level executor config
386→    const collectionExecutorConfig = parseExecutorConfig(
387→      collection.executorType,
388→      collection.executorConfig
389→    );
390→
391→    // Resolve executor config: Agent → Collection → Default
392→    const resolvedConfig = resolveExecutorConfig(agentExecutorConfig, collectionExecutorConfig);
393→
394→    // Parse collection-level env vars and merge with agent env vars
395→    // When callerEnvVars is provided, skip collection env vars entirely
396→    const collectionEnvVars = useCallerEnvVars ? {} : parseEnvVars(collection.envVars);
397→    const mergedEnvVars = mergeEnvVars(collectionEnvVars, agentEnvVars);
398→
399→    for (const collectionTool of collection.tools) {
400→      const tool = collectionTool.tool;
401→      const toolKey = `${tool.package.npmPackageName}::${tool.name}`;
402→
403→      // Avoid duplicates
404→      if (seenTools.has(toolKey)) continue;
405→      seenTools.add(toolKey);
406→
407→      const toolName = sanitizeToolName(`${tool.package.npmPackageName}-${tool.name}`);
408→      tools[toolName] = createToolDefinition(tool, resolvedConfig, mergedEnvVars);
409→    }
410→  }
411→
412→  // Add individual tools (may override collection tools)
413→  // Individual tools use agent config or system default (no collection context)
414→  // Individual tools only use agent env vars (no collection context)
415→  const individualToolConfig = agentExecutorConfig ?? { type: 'default' as const };
416→
417→  for (const agentTool of agent.tools) {
418→    const tool = agentTool.tool;
419→    const toolKey = `${tool.package.npmPackageName}::${tool.name}`;
420→
421→    // Skip if already added from collections
422→    if (seenTools.has(toolKey)) continue;
423→    seenTools.add(toolKey);
424→
425→    const toolName = sanitizeToolName(`${tool.package.npmPackageName}-${tool.name}`);
426→    tools[toolName] = createToolDefinition(tool, individualToolConfig, agentEnvVars);
427→  }
428→
429→  return tools;
430→}
431→
432→/**
433→ * Get list of tool names for an agent (for display)
434→ */
435→export function getAgentToolNames(agent: AgentWithRelations): string[] {
436→  const names: string[] = [];
437→  const seenTools = new Set<string>();
438→
439→  for (const agentCollection of agent.collections) {
440→    for (const collectionTool of agentCollection.collection.tools) {
441→      const tool = collectionTool.tool;
442→      const toolKey = `${tool.package.npmPackageName}::${tool.name}`;
443→      if (!seenTools.has(toolKey)) {
444→        seenTools.add(toolKey);
445→        names.push(sanitizeToolName(`${tool.package.npmPackageName}-${tool.name}`));
446→      }
447→    }
448→  }
449→
450→  for (const agentTool of agent.tools) {
451→    const tool = agentTool.tool;
452→    const toolKey = `${tool.package.npmPackageName}::${tool.name}`;
453→    if (!seenTools.has(toolKey)) {
454→      seenTools.add(toolKey);
455→      names.push(sanitizeToolName(`${tool.package.npmPackageName}-${tool.name}`));
456→    }
457→  }
458→
459→  return names;
460→}
