  1→/**
  2→ * TPMJS Agent Sandbox Server (Deno)
  3→ *
  4→ * Stateful execution server with session-scoped filesystem persistence.
  5→ * Based on the Railway executor but adds session management so files
  6→ * created by one tool call persist for subsequent calls within the same conversation.
  7→ */
  8→
  9→// Import zod-to-json-schema for Zod v3 support
 10→import { zodToJsonSchema } from 'https://esm.sh/zod-to-json-schema@3.25.0';
 11→
 12→// ─── Crash Protection ───────────────────────────────────────────────────────
 13→globalThis.addEventListener('unhandledrejection', (event) => {
 14→  event.preventDefault();
 15→  console.error('⚠️  Unhandled promise rejection (caught, process continues):', event.reason);
 16→});
 17→
 18→globalThis.addEventListener('error', (event) => {
 19→  console.error('⚠️  Uncaught error (caught, process continues):', event.error || event.message);
 20→  event.preventDefault();
 21→});
 22→
 23→// ─── Configuration ──────────────────────────────────────────────────────────
 24→const PORT = Number(Deno.env.get('PORT') || '3002');
 25→const EXECUTOR_API_KEY = Deno.env.get('EXECUTOR_API_KEY');
 26→const MAX_CONCURRENT_SESSIONS = Number(Deno.env.get('MAX_CONCURRENT_SESSIONS') || '50');
 27→const DEFAULT_SESSION_TTL_SECONDS = Number(Deno.env.get('DEFAULT_SESSION_TTL_SECONDS') || '86400');
 28→const SESSION_DISK_QUOTA_MB = Number(Deno.env.get('SESSION_DISK_QUOTA_MB') || '100');
 29→const SESSIONS_BASE_DIR = '/tmp/tpmjs-sandbox/sessions';
 30→
 31→// ─── Metrics ─────────────────────────────────────────────────────────────────
 32→
 33→const metrics = {
 34→  totalExecutions: 0,
 35→  successfulExecutions: 0,
 36→  failedExecutions: 0,
 37→  totalSessionsCreated: 0,
 38→  totalSessionsDestroyed: 0,
 39→  startTime: Date.now(),
 40→};
 41→
 42→// Module cache
 43→const CACHE_TTL_MS = 2 * 60 * 1000;
 44→const MAX_CACHE_SIZE = 200;
 45→
 46→interface CacheEntry {
 47→  // biome-ignore lint/suspicious/noExplicitAny: Tool types are dynamic
 48→  module: any;
 49→  expiresAt: number;
 50→  isFactory: boolean;
 51→}
 52→
 53→const moduleCache = new Map<string, CacheEntry>();
 54→
 55→// ─── Session Management ─────────────────────────────────────────────────────
 56→
 57→interface Session {
 58→  sessionId: string;
 59→  workDir: string;
 60→  createdAt: Date;
 61→  expiresAt: Date;
 62→  toolCallCount: number;
 63→}
 64→
 65→const sessions = new Map<string, Session>();
 66→
 67→function getSessionWorkDir(sessionId: string): string {
 68→  // Sanitize sessionId to be filesystem-safe
 69→  const safe = sessionId.replace(/[^a-zA-Z0-9_:-]/g, '_');
 70→  return `${SESSIONS_BASE_DIR}/${safe}/workspace`;
 71→}
 72→
 73→async function createSession(
 74→  sessionId: string,
 75→  timeoutSeconds?: number
 76→): Promise<Session & { resumed: boolean }> {
 77→  const ttl = timeoutSeconds ?? DEFAULT_SESSION_TTL_SECONDS;
 78→
 79→  // Idempotent: if session exists, extend TTL and return it
 80→  const existing = sessions.get(sessionId);
 81→  if (existing) {
 82→    existing.expiresAt = new Date(Date.now() + ttl * 1000);
 83→    console.log(`🔄 Session resumed: ${sessionId} (TTL extended to ${ttl}s)`);
 84→    return { ...existing, resumed: true };
 85→  }
 86→
 87→  // Check concurrent session limit
 88→  if (sessions.size >= MAX_CONCURRENT_SESSIONS) {
 89→    throw new Error(
 90→      `Maximum concurrent sessions reached (${MAX_CONCURRENT_SESSIONS}). Try again later.`
 91→    );
 92→  }
 93→
 94→  const workDir = getSessionWorkDir(sessionId);
 95→
 96→  // Create workspace directory
 97→  await Deno.mkdir(workDir, { recursive: true });
 98→
 99→  const session: Session = {
100→    sessionId,
101→    workDir,
102→    createdAt: new Date(),
103→    expiresAt: new Date(Date.now() + ttl * 1000),
104→    toolCallCount: 0,
105→  };
106→
107→  sessions.set(sessionId, session);
108→  metrics.totalSessionsCreated++;
109→  console.log(`✅ Session created: ${sessionId} (TTL: ${ttl}s, workDir: ${workDir})`);
110→
111→  return { ...session, resumed: false };
112→}
113→
114→async function destroySession(sessionId: string): Promise<boolean> {
115→  const session = sessions.get(sessionId);
116→  if (!session) {
117→    return false;
118→  }
119→
120→  sessions.delete(sessionId);
121→
122→  // Clean up workspace directory
123→  try {
124→    await Deno.remove(session.workDir, { recursive: true });
125→    // Also remove parent directory (the sessionId dir)
126→    const parentDir = session.workDir.replace(/\/workspace$/, '');
127→    await Deno.remove(parentDir, { recursive: true }).catch(() => {});
128→  } catch {
129→    // Directory may already be cleaned up
130→  }
131→
132→  metrics.totalSessionsDestroyed++;
133→  console.log(`🗑️  Session destroyed: ${sessionId}`);
134→  return true;
135→}
136→
137→function getSession(sessionId: string): Session | null {
138→  const session = sessions.get(sessionId);
139→  if (!session) return null;
140→
141→  // Check if expired
142→  if (new Date() > session.expiresAt) {
143→    // Mark for cleanup but don't block
144→    destroySession(sessionId).catch(() => {});
145→    return null;
146→  }
147→
148→  return session;
149→}
150→
151→// ─── Session Cleanup ────────────────────────────────────────────────────────
152→
153→async function cleanupExpiredSessions(): Promise<void> {
154→  const now = new Date();
155→  let cleaned = 0;
156→
157→  for (const [sessionId, session] of sessions.entries()) {
158→    if (now > session.expiresAt) {
159→      await destroySession(sessionId).catch(() => {});
160→      cleaned++;
161→    }
162→  }
163→
164→  if (cleaned > 0) {
165→    console.log(`🗑️  Cleaned ${cleaned} expired sessions (${sessions.size} remaining)`);
166→  }
167→}
168→
169→// Run session cleanup every 60 seconds
170→setInterval(cleanupExpiredSessions, 60 * 1000);
171→
172→// ─── Module Cache ───────────────────────────────────────────────────────────
173→
174→function getCachedModule(cacheKey: string): CacheEntry | null {
175→  const entry = moduleCache.get(cacheKey);
176→  if (!entry) return null;
177→  if (Date.now() > entry.expiresAt) {
178→    moduleCache.delete(cacheKey);
179→    return null;
180→  }
181→  return entry;
182→}
183→
184→// biome-ignore lint/suspicious/noExplicitAny: Tool types are dynamic
185→function setCachedModule(cacheKey: string, module: any, isFactory: boolean): void {
186→  if (moduleCache.size >= MAX_CACHE_SIZE) {
187→    const entriesToEvict = Math.max(1, Math.floor(MAX_CACHE_SIZE * 0.2));
188→    const keys = Array.from(moduleCache.keys());
189→    for (let i = 0; i < entriesToEvict && i < keys.length; i++) {
190→      moduleCache.delete(keys[i]);
191→    }
192→  }
193→  moduleCache.set(cacheKey, {
194→    module,
195→    expiresAt: Date.now() + CACHE_TTL_MS,
196→    isFactory,
197→  });
198→}
199→
200→function cleanupExpiredCache(): void {
201→  const now = Date.now();
202→  for (const [key, entry] of moduleCache.entries()) {
203→    if (now > entry.expiresAt) {
204→      moduleCache.delete(key);
205→    }
206→  }
207→}
208→
209→setInterval(cleanupExpiredCache, 60 * 1000);
210→
211→// ─── Auth Middleware ─────────────────────────────────────────────────────────
212→
213→function checkAuth(req: Request): boolean {
214→  if (!EXECUTOR_API_KEY) return true;
215→  const authHeader = req.headers.get('Authorization');
216→  if (!authHeader) return false;
217→  const token = authHeader.replace('Bearer ', '');
218→  return token === EXECUTOR_API_KEY;
219→}
220→
221→// ─── CORS Headers ───────────────────────────────────────────────────────────
222→
223→function corsHeaders(): Record<string, string> {
224→  return {
225→    'Access-Control-Allow-Origin': '*',
226→    'Access-Control-Allow-Methods': 'GET, POST, DELETE, OPTIONS',
227→    'Access-Control-Allow-Headers': 'Content-Type, Authorization',
228→  };
229→}
230→
231→// ─── Built-in Sandbox Shell Tools ────────────────────────────────────────────
232→// These are built into the server to avoid loading @tpmjs/sandbox-shell from esm.sh.
233→// They implement the 4 sandbox tools: shellExec, readFile, writeFile, listFiles.
234→
235→const SHELL_MAX_STDOUT = 100 * 1024; // 100 KB
236→const SHELL_MAX_READ_SIZE = 500 * 1024; // 500 KB
237→const SHELL_DEFAULT_TIMEOUT_MS = 30_000;
238→const SHELL_MAX_TIMEOUT_MS = 300_000;
239→const SHELL_MAX_LIST_ENTRIES = 1_000;
240→const SHELL_DEFAULT_MAX_DEPTH = 3;
241→
242→function resolveSandboxPath(workDir: string, relativePath: string): string {
243→  const cleaned = relativePath.replace(/^\/+/, '');
244→  const resolved = `${workDir}/${cleaned}`.replace(/\/+/g, '/');
245→  const parts = resolved.split('/');
246→  const normalized: string[] = [];
247→  for (const part of parts) {
248→    if (part === '..') {
249→      normalized.pop();
250→    } else if (part !== '.' && part !== '') {
251→      normalized.push(part);
252→    }
253→  }
254→  const final = '/' + normalized.join('/');
255→  const normalizedWorkDir = '/' + workDir.replace(/^\/+/, '').replace(/\/+$/, '');
256→  if (!final.startsWith(normalizedWorkDir)) {
257→    throw new Error(`Path escapes sandbox workspace: ${relativePath}`);
258→  }
259→  return final;
260→}
261→
262→function truncateText(text: string, maxBytes: number): { text: string; truncated: boolean } {
263→  const encoder = new TextEncoder();
264→  const bytes = encoder.encode(text);
265→  if (bytes.length <= maxBytes) {
266→    return { text, truncated: false };
267→  }
268→  const decoder = new TextDecoder('utf-8', { fatal: false });
269→  return {
270→    text: decoder.decode(bytes.slice(0, maxBytes)) + '\n... [truncated]',
271→    truncated: true,
272→  };
273→}
274→
275→async function collectStream(
276→  stream: ReadableStream<Uint8Array>,
277→  maxBytes: number = SHELL_MAX_STDOUT * 2
278→): Promise<Uint8Array> {
279→  const reader = stream.getReader();
280→  const chunks: Uint8Array[] = [];
281→  let totalLength = 0;
282→  try {
283→    while (true) {
284→      const { done, value } = await reader.read();
285→      if (done) break;
286→      chunks.push(value);
287→      totalLength += value.length;
288→      if (totalLength > maxBytes) {
289→        reader.cancel().catch(() => {});
290→        break;
291→      }
292→    }
293→  } finally {
294→    reader.releaseLock();
295→  }
296→  const cappedLength = Math.min(totalLength, maxBytes);
297→  const result = new Uint8Array(cappedLength);
298→  let offset = 0;
299→  for (const chunk of chunks) {
300→    const copyLen = Math.min(chunk.length, cappedLength - offset);
301→    if (copyLen <= 0) break;
302→    result.set(chunk.subarray(0, copyLen), offset);
303→    offset += copyLen;
304→  }
305→  return result.subarray(0, offset);
306→}
307→
308→// biome-ignore lint/suspicious/noExplicitAny: Built-in tool params are dynamic
309→const builtinSandboxTools: Record<string, { execute: (params: any) => Promise<any> }> = {
310→  shellExec: {
311→    async execute({ command, timeout, _sandboxWorkDir }) {
312→      if (!_sandboxWorkDir) {
313→        throw new Error('shellExec requires a sandbox session (_sandboxWorkDir not set)');
314→      }
315→      const timeoutMs = Math.min(
316→        Math.max(timeout ?? SHELL_DEFAULT_TIMEOUT_MS, 1000),
317→        SHELL_MAX_TIMEOUT_MS
318→      );
319→      const startTime = Date.now();
320→      const cmd = new Deno.Command('sh', {
321→        args: ['-c', command],
322→        cwd: _sandboxWorkDir,
323→        stdout: 'piped',
324→        stderr: 'piped',
325→      });
326→      const child = cmd.spawn();
327→      let timedOut = false;
328→      const timer = setTimeout(() => {
329→        timedOut = true;
330→        try {
331→          child.kill('SIGTERM');
332→          setTimeout(() => {
333→            try {
334→              child.kill('SIGKILL');
335→            } catch {
336→              // Already exited
337→            }
338→          }, 2000);
339→        } catch {
340→          // Process may have already exited
341→        }
342→      }, timeoutMs);
343→      try {
344→        const [stdoutBytes, stderrBytes, status] = await Promise.all([
345→          collectStream(child.stdout),
346→          collectStream(child.stderr),
347→          child.status,
348→        ]);
349→        clearTimeout(timer);
350→        const durationMs = Date.now() - startTime;
351→        const decoder = new TextDecoder('utf-8', { fatal: false });
352→        const stdoutRaw = decoder.decode(stdoutBytes);
353→        const stderrRaw = decoder.decode(stderrBytes);
354→        const stdout = truncateText(stdoutRaw, SHELL_MAX_STDOUT);
355→        const stderr = truncateText(stderrRaw, SHELL_MAX_STDOUT);
356→        return {
357→          stdout: stdout.text,
358→          stderr: timedOut ? `[TIMEOUT after ${timeoutMs}ms] ${stderr.text}` : stderr.text,
359→          exitCode: timedOut ? 137 : status.code,
360→          durationMs,
361→          truncated: stdout.truncated || stderr.truncated,
362→        };
363→      } catch (error) {
364→        clearTimeout(timer);
365→        throw new Error(
366→          `Shell execution failed: ${error instanceof Error ? error.message : String(error)}`
367→        );
368→      }
369→    },
370→  },
371→
372→  readFile: {
373→    async execute({ path: filePath, _sandboxWorkDir }) {
374→      if (!_sandboxWorkDir) {
375→        throw new Error('readFile requires a sandbox session (_sandboxWorkDir not set)');
376→      }
377→      const resolved = resolveSandboxPath(_sandboxWorkDir, filePath);
378→      try {
379→        const realPath = await Deno.realPath(resolved);
380→        const normalizedWorkDir = '/' + _sandboxWorkDir.replace(/^\/+/, '').replace(/\/+$/, '');
381→        if (!realPath.startsWith(normalizedWorkDir)) {
382→          throw new Error(`Path escapes sandbox workspace via symlink: ${filePath}`);
383→        }
384→      } catch (error) {
385→        if (error instanceof Error && error.message.includes('escapes sandbox')) {
386→          throw error;
387→        }
388→      }
389→      const content = await Deno.readTextFile(resolved);
390→      const { text, truncated } = truncateText(content, SHELL_MAX_READ_SIZE);
391→      const stat = await Deno.stat(resolved);
392→      return { content: text, path: filePath, size: stat.size, truncated };
393→    },
394→  },
395→
396→  writeFile: {
397→    async execute({ path: filePath, content, createDirs = true, _sandboxWorkDir }) {
398→      if (!_sandboxWorkDir) {
399→        throw new Error('writeFile requires a sandbox session (_sandboxWorkDir not set)');
400→      }
401→      const resolved = resolveSandboxPath(_sandboxWorkDir, filePath);
402→      if (createDirs) {
403→        const parentDir = resolved.substring(0, resolved.lastIndexOf('/'));
404→        if (parentDir) {
405→          await Deno.mkdir(parentDir, { recursive: true });
406→        }
407→      }
408→      await Deno.writeTextFile(resolved, content);
409→      const encoder = new TextEncoder();
410→      const bytesWritten = encoder.encode(content).length;
411→      return { success: true, path: filePath, bytesWritten };
412→    },
413→  },
414→
415→  listFiles: {
416→    async execute({ path: dirPath = '.', recursive = false, maxDepth, _sandboxWorkDir }) {
417→      if (!_sandboxWorkDir) {
418→        throw new Error('listFiles requires a sandbox session (_sandboxWorkDir not set)');
419→      }
420→      const effectiveMaxDepth = maxDepth ?? SHELL_DEFAULT_MAX_DEPTH;
421→      const resolved = resolveSandboxPath(_sandboxWorkDir, dirPath);
422→      // biome-ignore lint/suspicious/noExplicitAny: File entry type
423→      const entries: any[] = [];
424→      let truncated = false;
425→      const normalizedWorkDir = '/' + _sandboxWorkDir.replace(/^\/+/, '').replace(/\/+$/, '');
426→
427→      async function walk(dir: string, depth: number, prefix: string): Promise<void> {
428→        if (entries.length >= SHELL_MAX_LIST_ENTRIES) {
429→          truncated = true;
430→          return;
431→        }
432→        for await (const entry of Deno.readDir(dir)) {
433→          if (entries.length >= SHELL_MAX_LIST_ENTRIES) {
434→            truncated = true;
435→            return;
436→          }
437→          const entryPath = `${dir}/${entry.name}`;
438→          const displayName = prefix ? `${prefix}/${entry.name}` : entry.name;
439→          if (entry.isSymlink) {
440→            try {
441→              const realPath = await Deno.realPath(entryPath);
442→              if (!realPath.startsWith(normalizedWorkDir)) {
443→                continue;
444→              }
445→            } catch {
446→              continue;
447→            }
448→          }
449→          let size: number | null = null;
450→          if (entry.isFile) {
451→            try {
452→              const info = await Deno.stat(entryPath);
453→              size = info.size;
454→            } catch {
455→              // Permission or race condition
456→            }
457→          }
458→          entries.push({
459→            name: displayName,
460→            type: entry.isDirectory ? 'directory' : entry.isSymlink ? 'symlink' : 'file',
461→            size,
462→          });
463→          if (recursive && entry.isDirectory && depth < effectiveMaxDepth) {
464→            await walk(entryPath, depth + 1, displayName);
465→          }
466→        }
467→      }
468→
469→      await walk(resolved, 0, '');
470→      return { path: dirPath, entries, truncated };
471→    },
472→  },
473→};
