477→// biome-ignore lint/suspicious/noExplicitAny: Dynamic tool loading
478→async function loadTool(
479→  packageName: string,
480→  name: string,
481→  version: string,
482→  importUrl?: string
483→): Promise<any> {
484→  // Built-in sandbox tools — no esm.sh import needed
485→  if (packageName === '@tpmjs/sandbox-shell' || packageName === '@tpmjs/official-sandbox-shell') {
486→    const builtin = builtinSandboxTools[name];
487→    if (!builtin) {
488→      throw new Error(
489→        `Built-in sandbox tool "${name}" not found. Available: ${Object.keys(builtinSandboxTools).join(', ')}`
490→      );
491→    }
492→    return builtin;
493→  }
494→  const cacheKey = `${packageName}::${name}`;
495→
496→  const cached = getCachedModule(cacheKey);
497→  if (cached) {
498→    return cached.module;
499→  }
500→
501→  const url = importUrl || `https://esm.sh/${packageName}@${version}`;
502→  console.log(`📦 Importing: ${url}`);
503→
504→  const module = await import(url);
505→  let rawExport = module[name];
506→
507→  if (!rawExport) {
508→    throw new Error(
509→      `Export "${name}" not found in module. Available: ${Object.keys(module).join(', ')}`
510→    );
511→  }
512→
513→  // Check if it's a factory function
514→  if (typeof rawExport === 'function' && !rawExport.description && !rawExport.execute) {
515→    console.log(`🏭 Detected factory function for ${cacheKey}, attempting to call...`);
516→
517→    let factoryResult = null;
518→
519→    // Strategy 1: no arguments
520→    try {
521→      factoryResult = rawExport();
522→      if (factoryResult?.description && factoryResult?.execute) {
523→        rawExport = factoryResult;
524→      } else {
525→        factoryResult = null;
526→      }
527→    } catch {
528→      factoryResult = null;
529→    }
530→
531→    // Strategy 2: empty config object
532→    if (!factoryResult) {
533→      try {
534→        factoryResult = rawExport({});
535→        if (factoryResult?.description && factoryResult?.execute) {
536→          rawExport = factoryResult;
537→        }
538→      } catch {
539→        // Not a factory
540→      }
541→    }
542→  }
543→
544→  const isFactory = rawExport !== module[name];
545→  setCachedModule(cacheKey, rawExport, isFactory);
546→
547→  return rawExport;
548→}
