611→// biome-ignore lint/complexity/noExcessiveCognitiveComplexity: Tool execution with session support
612→async function handleExecuteTool(req: Request): Promise<Response> {
613→  const startTime = Date.now();
614→
615→  try {
616→    const body = await req.json();
617→    const { packageName, name, version, importUrl, params, env, sessionId } = body;
618→
619→    if (!packageName || !name) {
620→      return Response.json(
621→        { success: false, error: 'Missing required fields: packageName, name' },
622→        { status: 400, headers: corsHeaders() }
623→      );
624→    }
625→
626→    // Load the tool
627→    const tool = await loadTool(packageName, name, version || 'latest', importUrl);
628→
629→    if (!tool || typeof tool.execute !== 'function') {
630→      return Response.json(
631→        { success: false, error: `"${name}" is not a valid tool (missing execute function)` },
632→        { status: 400, headers: corsHeaders() }
633→      );
634→    }
635→
636→    // Resolve session workspace for cwd if sessionId provided
637→    let cwd: string | undefined;
638→    if (sessionId) {
639→      const session = getSession(sessionId);
640→      if (session) {
641→        cwd = session.workDir;
642→        session.toolCallCount++;
643→        // Extend session TTL on each tool call
644→        session.expiresAt = new Date(Date.now() + DEFAULT_SESSION_TTL_SECONDS * 1000);
645→      }
646→    }
647→
648→    // Enforce disk quota before execution
649→    if (cwd) {
650→      const usageKB = await getDirectorySizeKB(cwd);
651→      const quotaKB = SESSION_DISK_QUOTA_MB * 1024;
652→      if (usageKB > quotaKB) {
653→        return Response.json(
654→          {
655→            success: false,
656→            error: `Session disk quota exceeded: ${Math.round(usageKB / 1024)}MB / ${SESSION_DISK_QUOTA_MB}MB`,
657→            executionTimeMs: Date.now() - startTime,
658→          },
659→          { status: 413, headers: corsHeaders() }
660→        );
661→      }
662→    }
663→
664→    // Set environment variables if provided
665→    if (env && typeof env === 'object') {
666→      for (const [key, value] of Object.entries(env)) {
667→        if (typeof value === 'string') {
668→          Deno.env.set(key, value);
669→        }
670→      }
671→    }
672→
673→    // Execute the tool, injecting cwd into params if session is active
674→    const executeParams = cwd ? { ...params, _sandboxWorkDir: cwd } : params;
675→    const output = await tool.execute(executeParams);
676→
677→    // Clean up injected env vars
678→    if (env && typeof env === 'object') {
679→      for (const key of Object.keys(env)) {
680→        try {
681→          Deno.env.delete(key);
682→        } catch {
683→          // Some vars may be read-only
684→        }
685→      }
686→    }
687→
688→    const executionTimeMs = Date.now() - startTime;
689→    metrics.totalExecutions++;
690→    metrics.successfulExecutions++;
691→
692→    return Response.json(
693→      { success: true, output, executionTimeMs },
694→      { status: 200, headers: corsHeaders() }
695→    );
696→  } catch (error) {
697→    const executionTimeMs = Date.now() - startTime;
698→    const message = error instanceof Error ? error.message : String(error);
699→    console.error('❌ Execute tool error:', message);
700→    metrics.totalExecutions++;
701→    metrics.failedExecutions++;
702→
703→    return Response.json(
704→      { success: false, error: message, executionTimeMs },
705→      { status: 200, headers: corsHeaders() }
706→    );
707→  }
708→}
