712→async function getDirectorySizeKB(dir: string): Promise<number> {
713→  try {
714→    const cmd = new Deno.Command('du', { args: ['-sk', dir], stdout: 'piped', stderr: 'piped' });
715→    const { stdout } = await cmd.output();
716→    const output = new TextDecoder().decode(stdout);
717→    const sizeKB = parseInt(output.split('\t')[0], 10);
718→    return isNaN(sizeKB) ? 0 : sizeKB;
719→  } catch {
720→    return 0;
721→  }
722→}
