777→async function handler(req: Request): Promise<Response> {
778→  const url = new URL(req.url);
779→  const { pathname } = url;
780→  const method = req.method;
781→
782→  // CORS preflight
783→  if (method === 'OPTIONS') {
784→    return new Response(null, { status: 204, headers: corsHeaders() });
785→  }
786→
787→  // Health check (no auth required)
788→  if (pathname === '/health' && method === 'GET') {
789→    return handleHealth();
790→  }
791→
792→  // Metrics (no auth required, for monitoring)
793→  if (pathname === '/metrics' && method === 'GET') {
794→    return handleMetrics();
795→  }
796→
797→  // Auth check for all other routes
798→  if (!checkAuth(req)) {
799→    return Response.json({ error: 'Unauthorized' }, { status: 401, headers: corsHeaders() });
800→  }
801→
802→  // Session endpoints
803→  if (pathname === '/sessions' && method === 'POST') {
804→    return handleCreateSession(req);
805→  }
806→
807→  const sessionMatch = pathname.match(/^\/sessions\/(.+)$/);
808→  if (sessionMatch) {
809→    const sessionId = decodeURIComponent(sessionMatch[1]);
810→    if (method === 'GET') {
811→      return handleGetSession(sessionId);
812→    }
813→    if (method === 'DELETE') {
814→      return handleDestroySession(sessionId);
815→    }
816→  }
817→
818→  // Tool execution
819→  if (pathname === '/execute-tool' && method === 'POST') {
820→    return handleExecuteTool(req);
821→  }
822→
823→  return Response.json({ error: 'Not Found' }, { status: 404, headers: corsHeaders() });
824→}
