 14→/**
 15→ * Parameter from TPMJS metadata
 16→ */
 17→interface TPMJSParameter {
 18→  name: string;
 19→  type: string;
 20→  required: boolean;
 21→  description: string;
 22→  default?: unknown;
 23→}
 24→
 25→/**
 26→ * Token usage breakdown
 27→ */
 28→export interface TokenBreakdown {
 29→  inputTokens: number;
 30→  toolDescTokens: number;
 31→  schemaTokens: number;
 32→  outputTokens: number;
 33→  totalTokens: number;
 34→  estimatedCost: number;
 35→}
 36→
 37→/**
 38→ * Convert TPMJS parameter type to Zod schema
 39→ */
 40→function typeToZodSchema(type: string): z.ZodTypeAny {
 41→  // Handle array types
 42→  if (type.endsWith('[]')) {
 43→    const baseType = type.slice(0, -2);
 44→    return z.array(typeToZodSchema(baseType));
 45→  }
 46→
 47→  // Handle union types (e.g., 'markdown' | 'mdx')
 48→  if (type.includes('|')) {
 49→    const types = type.split('|').map((t) => t.trim().replace(/'/g, ''));
 50→    return z.enum(types as [string, ...string[]]);
 51→  }
 52→
 53→  // Handle primitive types
 54→  switch (type) {
 55→    case 'string':
 56→      return z.string();
 57→    case 'number':
 58→      return z.number();
 59→    case 'boolean':
 60→      return z.boolean();
 61→    case 'object':
 62→      return z.object({});
 63→    default:
 64→      // Default to string for unknown types
 65→      return z.string();
 66→  }
 67→}
 68→
 69→/**
 70→ * Convert TPMJS parameters to Zod schema object
 71→ */
 72→// biome-ignore lint/suspicious/noExplicitAny: Zod requires any for dynamic schema objects
 73→export function tpmjsParamsToZodSchema(parameters: TPMJSParameter[]): z.ZodObject<any> {
 74→  const shape: Record<string, z.ZodTypeAny> = {};
 75→
 76→  for (const param of parameters) {
 77→    let schema = typeToZodSchema(param.type);
 78→
 79→    // Add description
 80→    schema = schema.describe(param.description);
 81→
 82→    // Make optional if not required
 83→    if (!param.required) {
 84→      schema = schema.optional();
 85→    }
 86→
 87→    shape[param.name] = schema;
 88→  }
 89→
 90→  return z.object(shape);
 91→}
