300→/**
301→ * Execute a tool using a sandbox executor (includes sessionId in request)
302→ */
303→export async function executeWithSandbox(
304→  url: string,
305→  apiKey: string | undefined,
306→  request: ExecuteToolRequest,
307→  sessionId: string,
308→  timeout: number = DEFAULT_TIMEOUT
309→): Promise<ExecuteToolResponse> {
310→  const startTime = Date.now();
311→
312→  const headers: Record<string, string> = {
313→    'Content-Type': 'application/json',
314→  };
315→
316→  if (apiKey) {
317→    headers.Authorization = `Bearer ${apiKey}`;
318→  }
319→
320→  // Retry on transient failures (network errors, 429, 502, 503)
321→  let lastError: unknown;
322→  for (let attempt = 0; attempt <= MAX_RETRIES; attempt++) {
323→    try {
324→      const controller = new AbortController();
325→      const timeoutId = setTimeout(() => controller.abort(), timeout);
326→
327→      const response = await fetch(`${url}/execute-tool`, {
328→        method: 'POST',
329→        headers,
330→        body: JSON.stringify({ ...request, sessionId }),
331→        signal: controller.signal,
332→      });
333→
334→      clearTimeout(timeoutId);
335→
336→      const executionTimeMs = Date.now() - startTime;
337→
338→      // Retry on 429 (capacity) or 502/503 (transient server issues)
339→      if (
340→        (response.status === 429 || response.status === 502 || response.status === 503) &&
341→        attempt < MAX_RETRIES
342→      ) {
343→        const delay = RETRY_BASE_DELAY_MS * 2 ** attempt;
344→        console.warn(
345→          `[Sandbox] Got ${response.status}, retrying in ${delay}ms (attempt ${attempt + 1})`
346→        );
347→        await new Promise((resolve) => setTimeout(resolve, delay));
348→        continue;
349→      }
350→
351→      if (!response.ok) {
352→        const errorData = (await response.json().catch(() => ({ error: 'Unknown error' }))) as {
353→          error?: string;
354→        };
355→        return {
356→          success: false,
357→          error: errorData.error || `Sandbox executor error: ${response.status}`,
358→          executionTimeMs,
359→        };
360→      }
361→
362→      const result = (await response.json()) as ExecuteToolResponse;
363→
364→      return {
365→        success: result.success,
366→        output: result.output,
367→        error: result.error,
368→        executionTimeMs: result.executionTimeMs || executionTimeMs,
369→      };
370→    } catch (error) {
371→      lastError = error;
372→
373→      if (error instanceof Error && error.name === 'AbortError') {
374→        return {
375→          success: false,
376→          error: 'Execution timeout',
377→          executionTimeMs: Date.now() - startTime,
378→        };
379→      }
380→
381→      // Retry on network errors
382→      if (attempt < MAX_RETRIES) {
383→        const msg = error instanceof Error ? error.message : String(error);
384→        if (
385→          msg.includes('ECONNREFUSED') ||
386→          msg.includes('fetch failed') ||
387→          msg.includes('ECONNRESET')
388→        ) {
389→          const delay = RETRY_BASE_DELAY_MS * 2 ** attempt;
390→          console.warn(
391→            `[Sandbox] Network error, retrying in ${delay}ms (attempt ${attempt + 1}):`,
392→            msg
393→          );
394→          await new Promise((resolve) => setTimeout(resolve, delay));
395→          continue;
396→        }
397→      }
398→
399→      return {
400→        success: false,
401→        error: error instanceof Error ? error.message : String(error),
402→        executionTimeMs: Date.now() - startTime,
403→      };
404→    }
405→  }
406→
407→  return {
408→    success: false,
409→    error: lastError instanceof Error ? lastError.message : String(lastError),
410→    executionTimeMs: Date.now() - startTime,
411→  };
412→}
