530→/**
531→ * Verify a custom executor URL is valid and operational
532→ *
533→ * @param url - Executor URL to verify
534→ * @param apiKey - Optional API key for authentication
535→ * @returns Verification result
536→ */
537→export async function verifyExecutor(
538→  url: string,
539→  apiKey?: string
540→): Promise<{
541→  valid: boolean;
542→  healthCheck?: { healthy: boolean; response?: ExecutorHealthResponse };
543→  testExecution?: { success: boolean; executionTimeMs: number };
544→  errors: string[];
545→}> {
546→  const errors: string[] = [];
547→
548→  // Validate URL format
549→  try {
550→    const parsed = new URL(url);
551→    if (parsed.protocol !== 'https:' && process.env.NODE_ENV === 'production') {
552→      errors.push('Custom executor URL must use HTTPS in production');
553→    }
554→  } catch {
555→    errors.push('Invalid URL format');
556→    return { valid: false, errors };
557→  }
558→
559→  // Check health endpoint
560→  const healthResult = await checkExecutorHealth(url, apiKey);
561→  if (!healthResult.healthy) {
562→    errors.push(healthResult.error || 'Health check failed');
563→  }
564→
565→  // Test execution (only if health check passed)
566→  let testResult: { success: boolean; executionTimeMs: number } | undefined;
567→  if (healthResult.healthy) {
568→    const execResult = await testExecutor(url, apiKey);
569→    testResult = {
570→      success: execResult.success,
571→      executionTimeMs: execResult.executionTimeMs,
572→    };
573→    if (!execResult.success) {
574→      errors.push(execResult.error || 'Test execution failed');
575→    }
576→  }
577→
578→  return {
579→    valid: errors.length === 0,
580→    healthCheck: {
581→      healthy: healthResult.healthy,
582→      response: healthResult.response,
583→    },
584→    testExecution: testResult,
585→    errors,
586→  };
587→}
